import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");

  const handleUpload = async () => {
    if (!file) {
      alert("Please select a PDF file");
      return;
    }

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData
      });

      const data = await res.json();

      setTransactions(data.transactions);
      setType(data.detected_type);

    } catch (err) {
      console.error(err);
      alert("Upload failed");
    }
  };

  return (
    <div className="dashboard-main">

      {/* 🔥 NAVBAR */}
      <div className="navbar">
        <div className="logo">FinSight</div>
        <div className="tagline">Personal Expense Intelligence</div>
      </div>

      {/* 🔥 CONTENT */}
      <div className="dashboard-content">

        {/* TOP GRID */}
        <div className="top-section">

          {/* UPLOAD CARD */}
          <div className="card upload-card">
            <h3>Upload Statement</h3>

            <input
              type="file"
              accept=".pdf"
              onChange={(e) => setFile(e.target.files[0])}
            />

            <button onClick={handleUpload}>
              Upload & Analyze
            </button>
          </div>

          {/* SUMMARY CARD */}
          <div className="card summary-card">
            <h3>Summary</h3>

            <p><strong>Source:</strong> {type || "Not uploaded"}</p>
            <p><strong>Total Transactions:</strong> {transactions.length}</p>
          </div>

        </div>

        {/* TABLE SECTION */}
        {transactions.length > 0 && (
          <div className="card table-card">
            <h3>Transactions</h3>

            <table>
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Type</th>
                  <th>Description</th>
                  <th>Amount</th>
                </tr>
              </thead>

              <tbody>
                {transactions.map((txn, i) => (
                  <tr key={i}>
                    <td>{txn.date}</td>
                    <td className={txn.type === "debit" ? "debit" : "credit"}>
                      {txn.type}
                    </td>
                    <td>{txn.description}</td>
                    <td>₹{txn.amount}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
